AND NOT EXISTS (
    SELECT 1 FROM attendance_report_oa_evidence_exclusion exclusion
    WHERE exclusion.oa_attendance_document_id = ${documentAlias}.oa_attendance_document_id
      AND exclusion.attendance_source_id = ${documentAlias}.attendance_source_id
      AND exclusion.source_business_key = ${documentAlias}.source_business_key
      AND exclusion.source_version = ${documentAlias}.source_version
      AND exclusion.employee_id = ${matchedEmployeeExpression}
      AND exclusion.company_id = employee.company_id
      AND exclusion.company_id = #{companyId}
      AND exclusion.knowledge_at <= #{dataAsOf}
      AND (exclusion.reversed_at IS NULL OR exclusion.reversed_at > #{dataAsOf})
)

