WITH calendar_candidates AS ( SELECT DISTINCT employee.employee_id, day.business_date, day.day_type, CONCAT_WS( '|', assignment.attendance_group_assignment_id, group_revision.attendance_group_revision_id, version.work_calendar_version_id, day.work_calendar_day_id) AS authority_key FROM company company JOIN employee employee ON employee.company_id = company.company_id AND employee.created_at <= #{dataAsOf} JOIN attendance_group_assignment assignment ON assignment.employee_id = employee.employee_id AND assignment.created_at <= #{dataAsOf} JOIN attendance_assignment_timeline assignment_state ON assignment_state.attendance_group_assignment_id = assignment.attendance_group_assignment_id AND assignment_state.employee_id = employee.employee_id AND assignment_state.state = 'ACTIVE' AND assignment_state.recorded_at <= #{dataAsOf} JOIN attendance_group_revision group_revision ON group_revision.attendance_group_revision_id = assignment.attendance_group_revision_id AND group_revision.created_at <= #{dataAsOf} JOIN attendance_group attendance_group ON attendance_group.attendance_group_id = group_revision.attendance_group_id AND attendance_group.company_id = employee.company_id AND attendance_group.created_at <= #{dataAsOf} JOIN attendance_group_timeline group_state ON group_state.attendance_group_id = attendance_group.attendance_group_id AND group_state.attendance_group_revision_id = group_revision.attendance_group_revision_id AND group_state.state = 'ACTIVE' AND group_state.recorded_at <= #{dataAsOf} JOIN location_revision location_revision ON location_revision.location_revision_id = group_revision.location_revision_id AND location_revision.created_at <= #{dataAsOf} JOIN location location ON location.location_id = location_revision.location_id AND location.company_id = employee.company_id AND location.created_at <= #{dataAsOf} JOIN location_timeline location_state ON location_state.location_id = location.location_id AND location_state.location_revision_id = location_revision.location_revision_id AND location_state.state = 'ACTIVE' AND location_state.recorded_at <= #{dataAsOf} JOIN work_calendar calendar ON calendar.work_calendar_id = group_revision.work_calendar_id AND calendar.company_id = employee.company_id AND calendar.location_id = location.location_id AND calendar.created_at <= #{dataAsOf} JOIN calendar_publication_timeline timeline ON timeline.work_calendar_id = calendar.work_calendar_id AND timeline.state = 'PUBLISHED' AND timeline.recorded_at <= #{dataAsOf} JOIN work_calendar_version version ON version.work_calendar_version_id = timeline.work_calendar_version_id AND version.work_calendar_id = calendar.work_calendar_id AND version.created_at <= #{dataAsOf} JOIN work_calendar_day day ON day.work_calendar_version_id = version.work_calendar_version_id AND day.business_date >= #{periodStart} AND day.business_date < #{periodEndExclusive} AND day.created_at <= #{dataAsOf} WHERE company.company_id = #{companyId} AND company.status = 'ACTIVE' AND company.created_at <= #{dataAsOf}
AND 1 = 0
AND employee.employee_id IN
#{scopedEmployeeId}
AND assignment.effective_from <= day.business_date AND assignment_state.business_effective_from <= day.business_date AND group_revision.effective_from <= day.business_date AND group_state.business_effective_from <= day.business_date AND location_revision.effective_from <= day.business_date AND location_state.business_effective_from <= day.business_date AND timeline.business_effective_from <= day.business_date AND version.effective_from <= day.business_date AND version.effective_to > day.business_date AND location_revision.time_zone = version.time_zone_snapshot AND EXISTS ( SELECT 1 FROM employment_assignment employment JOIN organization_identity organization ON organization.organization_id = employment.organization_id AND organization.company_id = employee.company_id AND organization.identity_status = 'ACTIVE' AND organization.created_at <= #{dataAsOf} WHERE employment.employee_id = employee.employee_id AND employment.version_valid_to IS NULL AND employment.record_status = 'ACTIVE' AND DATE(employment.effective_from) <= day.business_date AND ( employment.effective_to IS NULL OR DATE(employment.effective_to) > day.business_date ) AND employment.created_at <= #{dataAsOf} ) AND NOT EXISTS ( SELECT 1 FROM attendance_group_assignment successor WHERE successor.supersedes_assignment_id = assignment.attendance_group_assignment_id AND successor.effective_from <= day.business_date AND successor.created_at <= #{dataAsOf} ) AND NOT EXISTS ( SELECT 1 FROM attendance_assignment_timeline newer_assignment WHERE newer_assignment.attendance_group_assignment_id = assignment_state.attendance_group_assignment_id AND newer_assignment.business_effective_from <= day.business_date AND newer_assignment.recorded_at <= #{dataAsOf} AND newer_assignment.event_sequence > assignment_state.event_sequence ) AND NOT EXISTS ( SELECT 1 FROM attendance_group_timeline newer_group WHERE newer_group.attendance_group_id = group_state.attendance_group_id AND newer_group.business_effective_from <= day.business_date AND newer_group.recorded_at <= #{dataAsOf} AND newer_group.event_sequence > group_state.event_sequence ) AND NOT EXISTS ( SELECT 1 FROM calendar_publication_timeline newer_calendar WHERE newer_calendar.work_calendar_id = timeline.work_calendar_id AND newer_calendar.business_effective_from <= day.business_date AND newer_calendar.recorded_at <= #{dataAsOf} AND ( newer_calendar.business_effective_from > timeline.business_effective_from OR ( newer_calendar.business_effective_from = timeline.business_effective_from AND newer_calendar.event_sequence > timeline.event_sequence ) ) ) AND NOT EXISTS ( SELECT 1 FROM location_timeline newer_location WHERE newer_location.location_id = location_state.location_id AND newer_location.business_effective_from <= day.business_date AND newer_location.recorded_at <= #{dataAsOf} AND newer_location.event_sequence > location_state.event_sequence ) ) SELECT employee_id AS employeeId, business_date AS businessDate, MIN(day_type) AS dayType, COUNT(DISTINCT authority_key) AS authorityCount, COUNT(DISTINCT day_type) AS distinctDayTypeCount FROM calendar_candidates GROUP BY employee_id, business_date ORDER BY employee_id, business_date

WITH ranked_document AS ( SELECT document.*, CASE WHEN document.source_status = 'UNKNOWN' AND document.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$' THEN 'PENDING' ELSE document.source_status END AS effective_status, ROW_NUMBER() OVER ( PARTITION BY document.attendance_source_id, document.source_business_key ORDER BY document.knowledge_rank DESC, document.created_at DESC, document.oa_attendance_document_id DESC ) AS version_rank FROM oa_attendance_document document WHERE document.created_at <= #{dataAsOf} ) SELECT oa.oa_attendance_document_id AS oaAttendanceDocumentId, oa.source_business_key AS sourceBusinessKey, oa.document_type AS documentType, oa.leave_type AS leaveType, match_decision.employee_id AS employeeId, employee.employee_number AS employeeNumber, match_decision.employment_period_id AS employmentAssignmentId, COALESCE(normalized.interval_start, normalized.point_instant) AS startInstant, COALESCE(normalized.interval_end, normalized.point_instant) AS endInstant, oa.effective_status AS sourceStatus, oa.source_version AS sourceVersion, context.overtime_type AS overtimeType FROM ranked_document oa JOIN normalized_attendance_record normalized ON normalized.normalized_attendance_record_id = oa.normalized_attendance_record_id AND normalized.validation_status = 'VALID' JOIN raw_attendance_fact raw ON raw.raw_attendance_fact_id = normalized.raw_attendance_fact_id JOIN employee_match_decision match_decision ON match_decision.normalized_attendance_record_id = normalized.normalized_attendance_record_id AND match_decision.match_status = 'MATCHED' JOIN employee employee ON employee.employee_id = match_decision.employee_id LEFT JOIN oa_attendance_document_context context ON context.oa_attendance_document_id = oa.oa_attendance_document_id WHERE oa.version_rank = 1
AND oa.effective_status IN ( 'APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING') AND oa.document_type IN ( 'LEAVE', 'TIME_OFF', 'OVERTIME', 'OUTING', 'TRIP', 'PUNCH_CORRECTION', 'EXEMPT_PUNCH') AND ( ( normalized.interval_start < #{windowEndExclusive} AND normalized.interval_end > #{windowStart} ) OR ( oa.document_type = 'PUNCH_CORRECTION' AND COALESCE( normalized.interval_start, normalized.point_instant) >= #{windowStart} AND COALESCE( normalized.interval_start, normalized.point_instant) < #{windowEndExclusive} )
) AND ( oa.document_type <> 'OVERTIME' OR ( context.activation_decision = 'ACTIVATED' AND context.overtime_type IS NOT NULL ) ) ORDER BY employee.employee_number, normalized.interval_start, oa.oa_attendance_document_id

WITH shift_template_names AS ( SELECT ranked.resource_id_ref AS shift_template_id, ranked.anchor_ref FROM ( SELECT metadata.resource_id_ref, metadata.anchor_ref, ROW_NUMBER() OVER ( PARTITION BY metadata.resource_id_ref ORDER BY CAST(COALESCE(metadata.policy_version, '0') AS DECIMAL(20, 0)) DESC, metadata.occurred_at DESC, metadata.event_id DESC ) AS rn FROM audit_event metadata WHERE metadata.resource_type = 'SHIFT_TEMPLATE_METADATA' AND metadata.action_code = 'SHIFT_TEMPLATE_NAME_CAPTURED' AND metadata.occurred_at <= #{dataAsOf} AND metadata.resource_id_ref IN ( SELECT company_shift.shift_template_id FROM shift_template company_shift WHERE company_shift.company_id = #{companyId} ) ) ranked WHERE ranked.rn = 1 ), latest_group_template_status AS ( SELECT ranked.resource_id_ref AS shift_template_id, ranked.action_code FROM ( SELECT latest_group_template.resource_id_ref, latest_group_template.action_code, ROW_NUMBER() OVER ( PARTITION BY latest_group_template.resource_id_ref ORDER BY CASE WHEN latest_group_template.policy_version IS NULL THEN 0 ELSE 1 END DESC, CAST(COALESCE( latest_group_template.policy_version, '0') AS DECIMAL(20, 0)) DESC, latest_group_template.occurred_at DESC, latest_group_template.event_id DESC ) AS rn FROM audit_event latest_group_template WHERE latest_group_template.resource_type = 'SHIFT_TEMPLATE' AND latest_group_template.action_code IN ( 'SHIFT_TEMPLATE_ACTIVE', 'SHIFT_TEMPLATE_INACTIVE') AND latest_group_template.occurred_at <= #{dataAsOf} AND latest_group_template.resource_id_ref IN ( SELECT company_shift.shift_template_id FROM shift_template company_shift WHERE company_shift.company_id = #{companyId} ) ) ranked WHERE ranked.rn = 1 ), latest_effective_template_status AS ( SELECT ranked.resource_id_ref AS shift_template_id, ranked.action_code FROM ( SELECT latest_effective_template.resource_id_ref, latest_effective_template.action_code, ROW_NUMBER() OVER ( PARTITION BY latest_effective_template.resource_id_ref ORDER BY CASE WHEN latest_effective_template.policy_version IS NULL THEN 0 ELSE 1 END DESC, CAST(COALESCE( latest_effective_template.policy_version, '0') AS DECIMAL(20, 0)) DESC, latest_effective_template.occurred_at DESC, latest_effective_template.event_id DESC ) AS rn FROM audit_event latest_effective_template WHERE latest_effective_template.resource_type = 'SHIFT_TEMPLATE' AND latest_effective_template.action_code IN ( 'SHIFT_TEMPLATE_ACTIVE', 'SHIFT_TEMPLATE_INACTIVE') AND latest_effective_template.occurred_at <= #{dataAsOf} AND latest_effective_template.resource_id_ref IN ( SELECT company_shift.shift_template_id FROM shift_template company_shift WHERE company_shift.company_id = #{companyId} ) ) ranked WHERE ranked.rn = 1 ), schedule_candidates AS ( SELECT DISTINCT employee.employee_id, calendar_day.business_date, assignment.attendance_group_assignment_id, group_revision.attendance_group_revision_id, calendar_version.work_calendar_version_id, calendar_day.work_calendar_day_id, effective_shift.shift_version_id, COALESCE( shift_template_names.anchor_ref, effective_shift_template.template_code ) AS shift_template_name, CONCAT_WS( '|', assignment.attendance_group_assignment_id, group_revision.attendance_group_revision_id, calendar_version.work_calendar_version_id, calendar_day.work_calendar_day_id, effective_shift.shift_version_id) AS schedule_authority_key, segment.segment_order, segment.start_local_time, segment.start_day_offset, segment.end_local_time, segment.end_day_offset FROM company company JOIN employee employee ON employee.company_id = company.company_id JOIN attendance_group_assignment assignment ON assignment.employee_id = employee.employee_id AND assignment.created_at <= #{dataAsOf} JOIN attendance_assignment_timeline assignment_state ON assignment_state.attendance_group_assignment_id = assignment.attendance_group_assignment_id AND assignment_state.employee_id = employee.employee_id AND assignment_state.state = 'ACTIVE' AND assignment_state.recorded_at <= #{dataAsOf} JOIN attendance_group_revision group_revision ON group_revision.attendance_group_revision_id = assignment.attendance_group_revision_id AND group_revision.created_at <= #{dataAsOf} JOIN attendance_group attendance_group ON attendance_group.attendance_group_id = group_revision.attendance_group_id AND attendance_group.company_id = employee.company_id AND attendance_group.created_at <= #{dataAsOf} JOIN attendance_group_timeline group_state ON group_state.attendance_group_id = attendance_group.attendance_group_id AND group_state.attendance_group_revision_id = group_revision.attendance_group_revision_id AND group_state.state = 'ACTIVE' AND group_state.recorded_at <= #{dataAsOf} JOIN location_revision location_revision ON location_revision.location_revision_id = group_revision.location_revision_id AND location_revision.created_at <= #{dataAsOf} JOIN location location ON location.location_id = location_revision.location_id AND location.company_id = employee.company_id AND location.created_at <= #{dataAsOf} JOIN location_timeline location_state ON location_state.location_id = location.location_id AND location_state.location_revision_id = location_revision.location_revision_id AND location_state.state = 'ACTIVE' AND location_state.recorded_at <= #{dataAsOf} JOIN work_calendar work_calendar ON work_calendar.work_calendar_id = group_revision.work_calendar_id AND work_calendar.company_id = employee.company_id AND work_calendar.location_id = location.location_id AND work_calendar.created_at <= #{dataAsOf} JOIN shift_template group_shift_template ON group_shift_template.shift_template_id = group_revision.shift_template_id AND group_shift_template.company_id = employee.company_id AND group_shift_template.location_id = location.location_id AND group_shift_template.created_at <= #{dataAsOf} LEFT JOIN latest_group_template_status latest_group_template ON latest_group_template.shift_template_id = group_shift_template.shift_template_id JOIN calendar_publication_timeline calendar_publication ON calendar_publication.work_calendar_id = work_calendar.work_calendar_id AND calendar_publication.state = 'PUBLISHED' AND calendar_publication.recorded_at <= #{dataAsOf} JOIN work_calendar_version calendar_version ON calendar_version.work_calendar_version_id = calendar_publication.work_calendar_version_id AND calendar_version.work_calendar_id = work_calendar.work_calendar_id AND calendar_version.created_at <= #{dataAsOf} JOIN work_calendar_day calendar_day ON calendar_day.work_calendar_version_id = calendar_version.work_calendar_version_id AND calendar_day.business_date >= #{periodStart} AND calendar_day.business_date < #{periodEndExclusive} AND calendar_day.day_type IN ( 'WORKDAY', 'SPECIAL_WORKDAY') AND calendar_day.created_at <= #{dataAsOf} JOIN shift_version effective_shift ON ( ( calendar_day.shift_version_override_id IS NULL AND effective_shift.shift_template_id = group_revision.shift_template_id ) OR effective_shift.shift_version_id = calendar_day.shift_version_override_id ) AND effective_shift.effective_from <= calendar_day.business_date AND effective_shift.created_at <= #{dataAsOf} AND EXISTS ( SELECT 1 FROM shift_publication_timeline current_shift_pub WHERE current_shift_pub.shift_template_id = effective_shift.shift_template_id AND current_shift_pub.shift_version_id = effective_shift.shift_version_id AND current_shift_pub.state = 'PUBLISHED' AND current_shift_pub.business_effective_from <= calendar_day.business_date AND current_shift_pub.recorded_at <= #{dataAsOf} ) AND NOT EXISTS ( SELECT 1 FROM shift_version newer_shift_version WHERE newer_shift_version.shift_template_id = effective_shift.shift_template_id AND newer_shift_version.effective_from <= calendar_day.business_date AND newer_shift_version.created_at <= #{dataAsOf} AND ( newer_shift_version.effective_from > effective_shift.effective_from OR ( newer_shift_version.effective_from = effective_shift.effective_from AND newer_shift_version.version_number > effective_shift.version_number ) ) AND EXISTS ( SELECT 1 FROM shift_publication_timeline newer_shift_pub WHERE newer_shift_pub.shift_template_id = newer_shift_version.shift_template_id AND newer_shift_pub.shift_version_id = newer_shift_version.shift_version_id AND newer_shift_pub.state = 'PUBLISHED' AND newer_shift_pub.business_effective_from <= calendar_day.business_date AND newer_shift_pub.recorded_at <= #{dataAsOf} ) ) JOIN shift_template effective_shift_template ON effective_shift_template.shift_template_id = effective_shift.shift_template_id AND effective_shift_template.company_id = employee.company_id AND effective_shift_template.location_id = location.location_id AND effective_shift_template.created_at <= #{dataAsOf} LEFT JOIN latest_effective_template_status latest_effective_template ON latest_effective_template.shift_template_id = effective_shift_template.shift_template_id LEFT JOIN shift_template_names ON shift_template_names.shift_template_id = effective_shift_template.shift_template_id JOIN shift_publication_timeline shift_publication ON shift_publication.shift_template_id = effective_shift.shift_template_id AND shift_publication.shift_version_id = effective_shift.shift_version_id AND shift_publication.state = 'PUBLISHED' AND shift_publication.recorded_at <= #{dataAsOf} JOIN JSON_TABLE( effective_shift.segments_json, '$.segments[*]' COLUMNS ( segment_order FOR ORDINALITY, segment_type VARCHAR(16) PATH '$.segmentType', start_local_time VARCHAR(8) PATH '$.startLocalTime', start_day_offset INT PATH '$.startDayOffset', end_local_time VARCHAR(8) PATH '$.endLocalTime', end_day_offset INT PATH '$.endDayOffset' ) ) segment ON segment.segment_type = 'WORK' AND segment.start_day_offset BETWEEN 0 AND 1 AND segment.end_day_offset BETWEEN segment.start_day_offset AND 1 AND segment.start_local_time REGEXP '^([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]$' AND segment.end_local_time REGEXP '^([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]$' AND TIMESTAMP( DATE_ADD( calendar_day.business_date, INTERVAL segment.end_day_offset DAY), CAST(segment.end_local_time AS TIME)) > TIMESTAMP( DATE_ADD( calendar_day.business_date, INTERVAL segment.start_day_offset DAY), CAST(segment.start_local_time AS TIME)) WHERE company.company_id = #{companyId} AND company.status = 'ACTIVE' AND company.created_at <= #{dataAsOf} AND employee.created_at <= #{dataAsOf}
AND 1 = 0
AND employee.employee_id IN
#{scopedEmployeeId}
AND assignment.effective_from <= calendar_day.business_date AND assignment_state.business_effective_from <= calendar_day.business_date AND group_revision.effective_from <= calendar_day.business_date AND group_state.business_effective_from <= calendar_day.business_date AND location_revision.effective_from <= calendar_day.business_date AND location_state.business_effective_from <= calendar_day.business_date AND calendar_publication.business_effective_from <= calendar_day.business_date AND calendar_version.effective_from <= calendar_day.business_date AND calendar_version.effective_to > calendar_day.business_date AND effective_shift.effective_from <= calendar_day.business_date AND shift_publication.business_effective_from <= calendar_day.business_date AND location_revision.time_zone = calendar_version.time_zone_snapshot AND location_revision.time_zone = effective_shift.time_zone_snapshot AND effective_shift.time_zone_snapshot = 'Asia/Shanghai' AND COALESCE( (latest_group_template.action_code), 'SHIFT_TEMPLATE_ACTIVE' ) <> 'SHIFT_TEMPLATE_INACTIVE' AND COALESCE( (latest_effective_template.action_code), 'SHIFT_TEMPLATE_ACTIVE' ) <> 'SHIFT_TEMPLATE_INACTIVE' AND EXISTS ( SELECT 1 FROM employment_assignment employment JOIN organization_identity organization ON organization.organization_id = employment.organization_id AND organization.company_id = employee.company_id AND organization.identity_status = 'ACTIVE' AND organization.created_at <= #{dataAsOf} WHERE employment.employee_id = employee.employee_id AND employment.version_valid_to IS NULL AND employment.record_status = 'ACTIVE' AND DATE(employment.effective_from) <= calendar_day.business_date AND ( employment.effective_to IS NULL OR DATE(employment.effective_to) > calendar_day.business_date ) AND employment.created_at <= #{dataAsOf} ) AND NOT EXISTS ( SELECT 1 FROM attendance_group_assignment successor WHERE successor.supersedes_assignment_id = assignment.attendance_group_assignment_id AND successor.effective_from <= calendar_day.business_date AND successor.created_at <= #{dataAsOf} ) AND NOT EXISTS ( SELECT 1 FROM attendance_assignment_timeline newer_assignment WHERE newer_assignment.attendance_group_assignment_id = assignment_state.attendance_group_assignment_id AND newer_assignment.business_effective_from <= calendar_day.business_date AND newer_assignment.recorded_at <= #{dataAsOf} AND newer_assignment.event_sequence > assignment_state.event_sequence ) AND NOT EXISTS ( SELECT 1 FROM attendance_group_timeline newer_group WHERE newer_group.attendance_group_id = group_state.attendance_group_id AND newer_group.business_effective_from <= calendar_day.business_date AND newer_group.recorded_at <= #{dataAsOf} AND newer_group.event_sequence > group_state.event_sequence ) AND NOT EXISTS ( SELECT 1 FROM location_timeline newer_location WHERE newer_location.location_id = location_state.location_id AND newer_location.business_effective_from <= calendar_day.business_date AND newer_location.recorded_at <= #{dataAsOf} AND newer_location.event_sequence > location_state.event_sequence ) AND NOT EXISTS ( SELECT 1 FROM calendar_publication_timeline newer_calendar WHERE newer_calendar.work_calendar_id = calendar_publication.work_calendar_id AND newer_calendar.business_effective_from <= calendar_day.business_date AND newer_calendar.recorded_at <= #{dataAsOf} AND ( newer_calendar.business_effective_from > calendar_publication.business_effective_from OR ( newer_calendar.business_effective_from = calendar_publication.business_effective_from AND newer_calendar.event_sequence > calendar_publication.event_sequence ) ) ) AND NOT EXISTS ( SELECT 1 FROM shift_publication_timeline newer_shift WHERE newer_shift.shift_template_id = shift_publication.shift_template_id AND newer_shift.business_effective_from <= calendar_day.business_date AND newer_shift.recorded_at <= #{dataAsOf} AND ( newer_shift.business_effective_from > shift_publication.business_effective_from OR ( newer_shift.business_effective_from = shift_publication.business_effective_from AND newer_shift.event_sequence > shift_publication.event_sequence ) ) ) ), unique_schedule_key AS ( SELECT employee_id, business_date FROM schedule_candidates GROUP BY employee_id, business_date HAVING COUNT(DISTINCT schedule_authority_key) = 1 ), resolved_schedule AS ( SELECT candidate.*, CONVERT_TZ( TIMESTAMP( DATE_ADD( candidate.business_date, INTERVAL candidate.start_day_offset DAY), CAST(candidate.start_local_time AS TIME)), '+08:00', '+00:00') AS segment_start_utc, CONVERT_TZ( TIMESTAMP( DATE_ADD( candidate.business_date, INTERVAL candidate.end_day_offset DAY), CAST(candidate.end_local_time AS TIME)), '+08:00', '+00:00') AS segment_end_utc FROM schedule_candidates candidate JOIN unique_schedule_key unique_key ON unique_key.employee_id = candidate.employee_id AND unique_key.business_date = candidate.business_date ) SELECT /*+ SET_VAR(optimizer_switch='derived_merge=off') SET_VAR(optimizer_search_depth=1) */ schedule.employee_id AS employeeId, schedule.business_date AS businessDate, CONCAT( schedule.shift_version_id, ':', schedule.business_date, ':', schedule.segment_order) AS segmentId, schedule.segment_start_utc AS segmentStart, schedule.segment_end_utc AS segmentEnd, CAST(NULL AS DATETIME(6)) AS arrivalWindowStart, CAST(NULL AS DATETIME(6)) AS arrivalWindowEnd, CAST(NULL AS DATETIME(6)) AS departureWindowStart, CAST(NULL AS DATETIME(6)) AS departureWindowEnd, schedule.shift_template_name AS shiftTemplateName FROM resolved_schedule schedule ORDER BY schedule.employee_id, schedule.business_date, schedule.segment_order

WITH date_ones AS ( SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 ), business_dates (business_date) AS ( SELECT DATE_ADD( CAST(#{periodStart} AS DATE), INTERVAL (ones.n + 10 * tens.n) DAY) FROM date_ones ones CROSS JOIN date_ones tens WHERE (ones.n + 10 * tens.n) < 62 AND DATE_ADD( CAST(#{periodStart} AS DATE), INTERVAL (ones.n + 10 * tens.n) DAY) < #{periodEndExclusive} ), group_authority_candidates AS ( SELECT DISTINCT employee.employee_id, business_date.business_date, assignment.attendance_group_assignment_id, attendance_group.attendance_group_id, group_revision.attendance_group_revision_id FROM company company JOIN employee employee ON employee.company_id = company.company_id AND employee.created_at <= #{dataAsOf} CROSS JOIN business_dates business_date JOIN attendance_group_assignment assignment ON assignment.employee_id = employee.employee_id AND assignment.effective_from <= business_date.business_date AND assignment.created_at <= #{dataAsOf} JOIN attendance_assignment_timeline assignment_state ON assignment_state.attendance_group_assignment_id = assignment.attendance_group_assignment_id AND assignment_state.employee_id = employee.employee_id AND assignment_state.state = 'ACTIVE' AND assignment_state.business_effective_from <= business_date.business_date AND assignment_state.recorded_at <= #{dataAsOf} JOIN attendance_group_revision group_revision ON group_revision.attendance_group_revision_id = assignment.attendance_group_revision_id AND group_revision.effective_from <= business_date.business_date AND group_revision.created_at <= #{dataAsOf} JOIN attendance_group attendance_group ON attendance_group.attendance_group_id = group_revision.attendance_group_id AND attendance_group.company_id = company.company_id AND attendance_group.created_at <= #{dataAsOf} JOIN attendance_group_timeline group_state ON group_state.attendance_group_id = attendance_group.attendance_group_id AND group_state.attendance_group_revision_id = group_revision.attendance_group_revision_id AND group_state.state = 'ACTIVE' AND group_state.business_effective_from <= business_date.business_date AND group_state.recorded_at <= #{dataAsOf} WHERE company.company_id = #{companyId} AND company.status = 'ACTIVE' AND company.created_at <= #{dataAsOf}
AND 1 = 0
AND employee.employee_id IN
#{scopedEmployeeId}
AND NOT EXISTS ( SELECT 1 FROM attendance_group_assignment successor WHERE successor.supersedes_assignment_id = assignment.attendance_group_assignment_id AND successor.effective_from <= business_date.business_date AND successor.created_at <= #{dataAsOf} ) AND NOT EXISTS ( SELECT 1 FROM attendance_assignment_timeline newer_assignment WHERE newer_assignment.attendance_group_assignment_id = assignment_state.attendance_group_assignment_id AND newer_assignment.business_effective_from <= business_date.business_date AND newer_assignment.recorded_at <= #{dataAsOf} AND newer_assignment.event_sequence > assignment_state.event_sequence ) AND NOT EXISTS ( SELECT 1 FROM attendance_group_timeline newer_group WHERE newer_group.attendance_group_id = group_state.attendance_group_id AND newer_group.business_effective_from <= business_date.business_date AND newer_group.recorded_at <= #{dataAsOf} AND newer_group.event_sequence > group_state.event_sequence ) ), group_policy_candidates AS ( SELECT authority.employee_id, authority.business_date, authority.attendance_group_assignment_id, authority.attendance_group_id, authority.attendance_group_revision_id, family.policy_kind, CASE WHEN JSON_TYPE(JSON_EXTRACT( version.parameters_json, '$.enabled')) = 'BOOLEAN' THEN JSON_UNQUOTE(JSON_EXTRACT( version.parameters_json, '$.enabled')) = 'true' ELSE NULL END AS policy_enabled, CASE WHEN JSON_TYPE(JSON_EXTRACT( version.parameters_json, '$.graceMinutes')) = 'INTEGER' THEN CAST(JSON_UNQUOTE(JSON_EXTRACT( version.parameters_json, '$.graceMinutes')) AS SIGNED) ELSE NULL END AS grace_minutes, CASE WHEN JSON_TYPE(JSON_EXTRACT( version.parameters_json, '$.monthlyUses')) = 'INTEGER' THEN CAST(JSON_UNQUOTE(JSON_EXTRACT( version.parameters_json, '$.monthlyUses')) AS SIGNED) ELSE NULL END AS monthly_uses, CASE WHEN JSON_TYPE(JSON_EXTRACT( version.parameters_json, '$.resetOnGroupChange')) = 'BOOLEAN' THEN JSON_UNQUOTE(JSON_EXTRACT( version.parameters_json, '$.resetOnGroupChange')) = 'true' ELSE NULL END AS reset_on_group_change FROM group_authority_candidates authority JOIN attendance_policy_binding_family family ON family.attendance_group_id = authority.attendance_group_id AND family.policy_kind IN ( 'LATE_GRACE', 'MONTHLY_LATE_EXEMPTION') AND family.created_at <= #{dataAsOf} JOIN attendance_policy_binding_revision revision ON revision.binding_family_id = family.binding_family_id AND revision.attendance_group_revision_id = authority.attendance_group_revision_id AND revision.effective_from <= authority.business_date AND revision.created_at <= #{dataAsOf} JOIN attendance_policy_scoped_version version ON version.scoped_version_id = revision.attendance_policy_scoped_version_id AND version.effective_from <= authority.business_date AND ( version.effective_to IS NULL OR version.effective_to > authority.business_date ) AND version.created_at <= #{dataAsOf} JOIN attendance_policy_scope policy_scope ON policy_scope.scope_id = version.scope_id AND policy_scope.company_id = #{companyId} AND policy_scope.created_at <= #{dataAsOf} JOIN attendance_policy_template template ON template.policy_template_id = policy_scope.policy_template_id AND template.template_code = family.policy_kind AND template.created_at <= #{dataAsOf} WHERE ( revision.change_reason NOT LIKE '@@effectiveTo=____-__-__%' OR CAST(SUBSTRING( revision.change_reason, 15, 10) AS DATE) > authority.business_date ) AND NOT EXISTS ( SELECT 1 FROM attendance_policy_binding_revision newer_revision WHERE newer_revision.binding_family_id = revision.binding_family_id AND newer_revision.revision_number > revision.revision_number AND newer_revision.effective_from <= authority.business_date AND newer_revision.created_at <= #{dataAsOf} ) AND EXISTS ( SELECT 1 FROM attendance_policy_lifecycle_event publication WHERE publication.scope_id = version.scope_id AND publication.scoped_version_id = version.scoped_version_id AND publication.action = 'PUBLISHED' AND publication.business_effective_from <= authority.business_date AND publication.recorded_at <= #{dataAsOf} AND NOT EXISTS ( SELECT 1 FROM attendance_policy_lifecycle_event later WHERE later.scope_id = publication.scope_id AND later.event_sequence > publication.event_sequence AND later.business_effective_from <= authority.business_date AND later.recorded_at <= #{dataAsOf} AND later.action IN ( 'DEACTIVATE_SCHEDULED', 'ROLLED_BACK') ) ) ), group_policy_summary AS ( SELECT authority.employee_id, authority.business_date, COUNT(DISTINCT CONCAT_WS( '|', authority.attendance_group_assignment_id, authority.attendance_group_id, authority.attendance_group_revision_id)) AS attendance_group_authority_count, SUM(CASE WHEN policy.policy_kind = 'LATE_GRACE' THEN 1 ELSE 0 END) AS late_grace_policy_count, MAX(CASE WHEN policy.policy_kind = 'LATE_GRACE' THEN policy.policy_enabled END) AS late_grace_enabled, MAX(CASE WHEN policy.policy_kind = 'LATE_GRACE' THEN policy.grace_minutes END) AS late_grace_minutes, SUM(CASE WHEN policy.policy_kind = 'MONTHLY_LATE_EXEMPTION' THEN 1 ELSE 0 END) AS monthly_late_exemption_policy_count, MAX(CASE WHEN policy.policy_kind = 'MONTHLY_LATE_EXEMPTION' THEN policy.policy_enabled END) AS monthly_late_exemption_enabled, MAX(CASE WHEN policy.policy_kind = 'MONTHLY_LATE_EXEMPTION' THEN policy.grace_minutes END) AS monthly_late_exemption_grace_minutes, MAX(CASE WHEN policy.policy_kind = 'MONTHLY_LATE_EXEMPTION' THEN policy.monthly_uses END) AS monthly_late_exemption_uses, MAX(CASE WHEN policy.policy_kind = 'MONTHLY_LATE_EXEMPTION' THEN policy.reset_on_group_change END) AS reset_on_group_change FROM group_authority_candidates authority LEFT JOIN group_policy_candidates policy ON policy.employee_id = authority.employee_id AND policy.business_date = authority.business_date AND policy.attendance_group_assignment_id = authority.attendance_group_assignment_id AND policy.attendance_group_id = authority.attendance_group_id AND policy.attendance_group_revision_id = authority.attendance_group_revision_id GROUP BY authority.employee_id, authority.business_date ), company_policy_candidates AS ( SELECT business_date.business_date, template.template_code, CASE WHEN JSON_TYPE(JSON_EXTRACT( version.parameters_json, '$.enabled')) = 'BOOLEAN' THEN JSON_UNQUOTE(JSON_EXTRACT( version.parameters_json, '$.enabled')) = 'true' ELSE NULL END AS policy_enabled, CASE WHEN JSON_TYPE(JSON_EXTRACT( version.parameters_json, '$.correctionWindowDays')) = 'INTEGER' THEN CAST(JSON_UNQUOTE(JSON_EXTRACT( version.parameters_json, '$.correctionWindowDays')) AS SIGNED) ELSE NULL END AS correction_window_days, CASE WHEN JSON_TYPE(JSON_EXTRACT( version.parameters_json, '$.deadlineMode')) = 'STRING' THEN JSON_UNQUOTE(JSON_EXTRACT( version.parameters_json, '$.deadlineMode')) ELSE NULL END AS correction_deadline_mode, CASE WHEN JSON_TYPE(JSON_EXTRACT( version.parameters_json, '$.submissionDeadlineHours')) = 'INTEGER' THEN CAST(JSON_UNQUOTE(JSON_EXTRACT( version.parameters_json, '$.submissionDeadlineHours')) AS SIGNED) ELSE NULL END AS overtime_submission_deadline_hours FROM business_dates business_date JOIN attendance_policy_template template ON template.template_code IN ( 'MISSING_PUNCH', 'OVERTIME_RECOGNITION') AND template.created_at <= #{dataAsOf} JOIN attendance_policy_scope policy_scope ON policy_scope.policy_template_id = template.policy_template_id AND policy_scope.company_id = #{companyId} AND policy_scope.created_at <= #{dataAsOf} JOIN attendance_policy_scoped_version version ON version.scope_id = policy_scope.scope_id AND version.effective_from <= business_date.business_date AND ( version.effective_to IS NULL OR version.effective_to > business_date.business_date ) AND version.created_at <= #{dataAsOf} WHERE EXISTS ( SELECT 1 FROM attendance_policy_lifecycle_event publication WHERE publication.scope_id = version.scope_id AND publication.scoped_version_id = version.scoped_version_id AND publication.action = 'PUBLISHED' AND publication.business_effective_from <= business_date.business_date AND publication.recorded_at <= #{dataAsOf} AND NOT EXISTS ( SELECT 1 FROM attendance_policy_lifecycle_event later WHERE later.scope_id = publication.scope_id AND later.event_sequence > publication.event_sequence AND later.business_effective_from <= business_date.business_date AND later.recorded_at <= #{dataAsOf} AND later.action IN ( 'DEACTIVATE_SCHEDULED', 'ROLLED_BACK') ) ) ), company_policy_summary AS ( SELECT business_date.business_date, SUM(CASE WHEN policy.template_code = 'MISSING_PUNCH' THEN 1 ELSE 0 END) AS missing_punch_policy_count, MAX(CASE WHEN policy.template_code = 'MISSING_PUNCH' THEN policy.policy_enabled END) AS missing_punch_enabled, MAX(CASE WHEN policy.template_code = 'MISSING_PUNCH' THEN policy.correction_window_days END) AS correction_window_days, MAX(CASE WHEN policy.template_code = 'MISSING_PUNCH' THEN policy.correction_deadline_mode END) AS correction_deadline_mode, SUM(CASE WHEN policy.template_code = 'OVERTIME_RECOGNITION' THEN 1 ELSE 0 END) AS overtime_policy_count, MAX(CASE WHEN policy.template_code = 'OVERTIME_RECOGNITION' THEN policy.policy_enabled END) AS overtime_enabled, MAX(CASE WHEN policy.template_code = 'OVERTIME_RECOGNITION' THEN policy.overtime_submission_deadline_hours END) AS overtime_submission_deadline_hours FROM business_dates business_date LEFT JOIN company_policy_candidates policy ON policy.business_date = business_date.business_date GROUP BY business_date.business_date ) SELECT group_policy.employee_id AS employeeId, group_policy.business_date AS businessDate, group_policy.attendance_group_authority_count AS attendanceGroupAuthorityCount, group_policy.late_grace_policy_count AS lateGracePolicyCount, group_policy.late_grace_enabled AS lateGraceEnabled, group_policy.late_grace_minutes AS lateGraceMinutes, group_policy.monthly_late_exemption_policy_count AS monthlyLateExemptionPolicyCount, group_policy.monthly_late_exemption_enabled AS monthlyLateExemptionEnabled, group_policy.monthly_late_exemption_grace_minutes AS monthlyLateExemptionGraceMinutes, group_policy.monthly_late_exemption_uses AS monthlyLateExemptionUses, group_policy.reset_on_group_change AS resetOnGroupChange, company_policy.missing_punch_policy_count AS missingPunchPolicyCount, company_policy.missing_punch_enabled AS missingPunchEnabled, company_policy.correction_window_days AS correctionWindowDays, company_policy.correction_deadline_mode AS correctionDeadlineMode, company_policy.overtime_policy_count AS overtimePolicyCount, company_policy.overtime_enabled AS overtimeEnabled, company_policy.overtime_submission_deadline_hours AS overtimeSubmissionDeadlineHours FROM group_policy_summary group_policy JOIN company_policy_summary company_policy ON company_policy.business_date = group_policy.business_date ORDER BY group_policy.employee_id, group_policy.business_date

SELECT roster_employee.employee_id,
       event.point_instant
FROM effective_attendance_event event
JOIN employee roster_employee
  ON roster_employee.company_id = #{companyId}
 AND roster_employee.employee_id = #{employeeId}
 AND (
        roster_employee.employee_id = event.employee_id
        OR roster_employee.employee_number = (
            SELECT punch_employee.employee_number
            FROM employee punch_employee
            WHERE punch_employee.employee_id = event.employee_id
        )
 )
WHERE event.event_kind = 'PUNCH_POINT'
  AND event.point_instant IS NOT NULL
  AND event.created_at <= #{dataAsOf}
  AND event.point_instant >= #{windowStart}
  AND event.point_instant < #{windowEndExclusive}
  AND (
        SELECT lifecycle.lifecycle_type
        FROM effective_event_lifecycle_fact lifecycle
        WHERE lifecycle.effective_attendance_event_id =
              event.effective_attendance_event_id
          AND lifecycle.knowledge_at <= #{dataAsOf}
        ORDER BY lifecycle.knowledge_at DESC,
                 lifecycle.effective_event_lifecycle_fact_id DESC
        LIMIT 1
  ) = 'ACTIVATED'
ORDER BY event.employee_id, event.point_instant

WITH ranked_document AS ( SELECT document.*, CASE WHEN document.source_status = 'UNKNOWN' AND document.source_version REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9})?:state=0:Asia/Shanghai$' THEN 'PENDING' ELSE document.source_status END AS effective_status, ROW_NUMBER() OVER ( PARTITION BY document.attendance_source_id, document.source_business_key ORDER BY document.knowledge_rank DESC, document.created_at DESC, document.oa_attendance_document_id DESC ) AS version_rank FROM oa_attendance_document document WHERE document.created_at <= #{dataAsOf} AND EXISTS ( SELECT 1 FROM oa_attendance_document employee_document JOIN employee_match_decision employee_match ON employee_match.normalized_attendance_record_id = employee_document.normalized_attendance_record_id WHERE employee_document.attendance_source_id = document.attendance_source_id AND employee_document.source_business_key = document.source_business_key AND employee_document.created_at <= #{dataAsOf} AND employee_match.employee_id = #{employeeId} AND employee_match.match_status = 'MATCHED' ) ) SELECT oa.oa_attendance_document_id AS oaAttendanceDocumentId, oa.source_business_key AS sourceBusinessKey, oa.document_type AS documentType, oa.leave_type AS leaveType, match_decision.employee_id AS employeeId, employee.employee_number AS employeeNumber, match_decision.employment_period_id AS employmentAssignmentId, COALESCE(normalized.interval_start, normalized.point_instant) AS startInstant, COALESCE(normalized.interval_end, normalized.point_instant) AS endInstant, oa.effective_status AS sourceStatus, oa.source_version AS sourceVersion, context.overtime_type AS overtimeType FROM ranked_document oa JOIN normalized_attendance_record normalized ON normalized.normalized_attendance_record_id = oa.normalized_attendance_record_id AND normalized.validation_status = 'VALID' JOIN raw_attendance_fact raw ON raw.raw_attendance_fact_id = normalized.raw_attendance_fact_id JOIN employee_match_decision match_decision ON match_decision.normalized_attendance_record_id = normalized.normalized_attendance_record_id AND match_decision.match_status = 'MATCHED' AND match_decision.employee_id = #{employeeId} JOIN employee employee ON employee.employee_id = match_decision.employee_id LEFT JOIN oa_attendance_document_context context ON context.oa_attendance_document_id = oa.oa_attendance_document_id WHERE oa.version_rank = 1
AND oa.effective_status IN ( 'APPROVED', 'MODIFIED', 'SUPPLEMENTED', 'PENDING') AND oa.document_type IN ( 'LEAVE', 'TIME_OFF', 'OVERTIME', 'OUTING', 'TRIP', 'PUNCH_CORRECTION', 'EXEMPT_PUNCH') AND ( ( normalized.interval_start < #{windowEndExclusive} AND normalized.interval_end > #{windowStart} ) OR ( oa.document_type = 'PUNCH_CORRECTION' AND COALESCE( normalized.interval_start, normalized.point_instant) >= #{windowStart} AND COALESCE( normalized.interval_start, normalized.point_instant) < #{windowEndExclusive} )
) AND ( oa.document_type <> 'OVERTIME' OR ( context.activation_decision = 'ACTIVATED' AND context.overtime_type IS NOT NULL ) ) ORDER BY employee.employee_number, normalized.interval_start, oa.oa_attendance_document_id

SELECT fact.employee_id AS employeeId,
       COUNT(*) AS lateDays
FROM attendance_report_daily_fact fact
WHERE fact.attendance_report_projection_id = (
        SELECT projection.attendance_report_projection_id
        FROM attendance_report_projection projection
        WHERE projection.company_id = #{companyId}
          AND projection.period_start = #{periodStart}
          AND projection.status = 'PUBLISHED'
        ORDER BY projection.published_at DESC,
                 projection.attendance_report_projection_id DESC
        LIMIT 1
  )
  AND fact.employee_id = #{employeeId}
  AND fact.business_date >= #{periodStart}
  AND fact.business_date < #{beforeDate}
  AND fact.late_minutes > 0
GROUP BY fact.employee_id
